import { describe, expect, it } from "vitest";
import { createApp } from "../src/app.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");

const VALID_FROM = "2026-01-01T00:00:00Z";
const VALID_UNTIL = "2027-01-01T00:00:00Z";

function makeApp() {
  const app = createApp({ clock: fixedClock });
  const createCoupon = (coupon: Record<string, unknown>) =>
    app.request("POST", "/coupons", {
      validFrom: VALID_FROM,
      validUntil: VALID_UNTIL,
      ...coupon,
    });
  const createOrder = (amountCents: number) =>
    app.request("POST", "/orders", { customer: "alice", amountCents });
  return { app, createCoupon, createOrder };
}

describe("apply coupon", () => {
  it("applies a percentage coupon", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "SAVE20", type: "PERCENT", value: 20 });
    createOrder(12000);

    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });

    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      id: 1,
      amountCents: 12000,
      discountCents: 2400,
      finalAmountCents: 9600,
      couponCode: "SAVE20",
    });
    expect(app.request("GET", "/orders/1").body).toMatchObject({
      discountCents: 2400,
      finalAmountCents: 9600,
      couponCode: "SAVE20",
    });
  });

  it("applies a fixed coupon", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "MINUS2000", type: "FIXED", value: 2000 });
    createOrder(12000);

    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "MINUS2000" });

    expect(res.body).toMatchObject({ discountCents: 2000, finalAmountCents: 10000 });
  });

  it("never discounts below zero", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "HUGE", type: "FIXED", value: 5000 });
    createOrder(1000);

    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "HUGE" });

    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });

  it("respects maxDiscountCents", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "HALF", type: "PERCENT", value: 50, maxDiscountCents: 3000 });
    createOrder(12000);

    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "HALF" });

    expect(res.body).toMatchObject({ discountCents: 3000, finalAmountCents: 9000 });
  });

  it("rounds percentage discounts down to whole cents", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "THIRTYTHREE", type: "PERCENT", value: 33 });
    createOrder(100);

    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "THIRTYTHREE" });

    expect(res.body).toMatchObject({ discountCents: 33, finalAmountCents: 67 });
  });

  it("records a redemption and increments usedCount", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "SAVE20", type: "PERCENT", value: 20 });
    createOrder(12000);

    app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });

    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
    const redemption = app.db
      .prepare("SELECT order_id, coupon_code, discount_cents FROM coupon_redemptions")
      .get() as Record<string, unknown>;
    expect(redemption).toMatchObject({ order_id: 1, coupon_code: "SAVE20", discount_cents: 2400 });
  });
});

describe("apply coupon validation", () => {
  it("rejects a missing coupon code", () => {
    const { app, createOrder } = makeApp();
    createOrder(12000);
    const res = app.request("POST", "/orders/1/apply-coupon", {});
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("returns 404 for an unknown order", () => {
    const res = makeApp().app.request("POST", "/orders/99/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("returns 404 for an unknown coupon", () => {
    const { app, createOrder } = makeApp();
    createOrder(12000);
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "NOPE" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("rejects a non-pending order", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "SAVE20", type: "PERCENT", value: 20 });
    createOrder(12000);
    app.request("POST", "/orders/1/pay");
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("rejects an order that already has a coupon", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "SAVE20", type: "PERCENT", value: 20 });
    createCoupon({ code: "MINUS100", type: "FIXED", value: 100 });
    createOrder(12000);
    app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "MINUS100" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_ALREADY_HAS_COUPON");
  });

  it("rejects a disabled coupon", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "SAVE20", type: "PERCENT", value: 20, status: "DISABLED" });
    createOrder(12000);
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_NOT_ACTIVE");
  });

  it("rejects an expired coupon", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "OLD", type: "PERCENT", value: 20, validUntil: "2026-05-01T00:00:00Z" });
    createOrder(12000);
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "OLD" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("rejects a coupon that is not yet valid", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "FUTURE", type: "PERCENT", value: 20, validFrom: "2026-12-01T00:00:00Z" });
    createOrder(12000);
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "FUTURE" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("rejects an order below the coupon minimum", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "BIGSPEND", type: "FIXED", value: 500, minAmountCents: 5000 });
    createOrder(1000);
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "BIGSPEND" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_MIN_AMOUNT_NOT_MET");
  });

  it("rejects a coupon whose usage limit is reached", () => {
    const { app, createCoupon, createOrder } = makeApp();
    createCoupon({ code: "ONCE", type: "FIXED", value: 100, usageLimit: 1 });
    createOrder(12000);
    createOrder(12000);
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "ONCE" }).status).toBe(200);
    const res = app.request("POST", "/orders/2/apply-coupon", { couponCode: "ONCE" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_LIMIT_REACHED");
  });
});
